import type { TableName } from '../db/Table';
import type { Duration as DurationType, TimeOfDay as TimeOfDayType } from '../db/types/Duration';
import type { FieldListValue } from '../db/types/FieldList';
import type { TemplateValueElement } from '../db';
declare global {
    /**
     * Duration helper function for creating duration values in Record() data.
     * Returns a string representation of a duration in ServiceNow format.
     *
     * @example
     * ```typescript
     * Duration({ days: 1, hours: 6, minutes: 30, seconds: 15 })
     * // Returns: '1970-01-02 06:30:15'
     * ```
     */
    function Duration<T extends DurationType>(value: T): T;
    /**
     * Time helper function for creating time-of-day values in Record() data.
     * Returns a string representation of time in ServiceNow format (UTC).
     *
     * The time is converted from the specified timezone (or system timezone if not provided) to UTC.
     *
     * @param value - Object with hours, minutes, and seconds properties
     * @param timeZone - Optional IANA timezone string (e.g., 'America/New_York', 'Europe/London', 'UTC').
     *                   Defaults to system timezone if not provided.
     *
     * @example
     * ```typescript
     * // Using system timezone (default)
     * Time({ hours: 14, minutes: 30, seconds: 0 })
     *
     * // Using explicit timezone
     * Time({ hours: 14, minutes: 30, seconds: 0 }, 'America/New_York')
     * // 14:30 EST -> 19:30 UTC
     *
     * // Using UTC (no conversion)
     * Time({ hours: 9, minutes: 0, seconds: 0 }, 'UTC')
     * // 09:00 UTC -> 09:00 UTC
     * ```
     */
    function Time<T extends TimeOfDayType>(value: T, timeZone?: string): T;
    /**
     * TemplateValue helper function for creating template value data in Record() data.
     * Returns a string. Template values are serialized as ServiceNow encoded query format.
     *
     * Supports generic table parameter for type-safe field IntelliSense.
     *
     * @example
     * ```typescript
     * // Generic - accepts any object
     * TemplateValue({ cost: 100, description: 'Item', active: true })
     * // Returns: 'cost=100^description=Item^active=true^EQ'
     *
     * // Table-specific - provides IntelliSense for sc_cat_item fields
     * TemplateValue<'sc_cat_item'>({ cost: 100, description: 'Item', category: 'Hardware' })
     * ```
     */
    function TemplateValue<T extends TableName = TableName, V extends TemplateValueElement<T> = TemplateValueElement<T>>(data: V): V;
    /**
     * FieldList helper function for creating list values in Record() data.
     * Returns a string. List values are serialized as comma-separated strings.
     *
     * Supports generic table parameter for type-safe field IntelliSense with dot-walk support.
     *
     * @example
     * ```typescript
     * // Generic - accepts any strings
     * FieldList(['name', 'description', 'cost'])
     * // Returns: 'name,description,cost'
     *
     * // Table-specific - provides IntelliSense for sc_cat_item fields
     * FieldList<'sc_cat_item'>(['name', 'description', 'cost', 'category', 'assigned_to.name'])
     *
     *
     * ```
     */
    function FieldList<T extends TableName = TableName, V extends FieldListValue<T> = FieldListValue<T>>(values: V): V;
}
